      "actor": "staff",
      "customer": "customer",
      "place": "cafe",
      "chair": "chair",
      "tray": "tray",
      "plate_stack": "plates",
      "cleaning_tool": "mop",
      "coffee": "coffee",
      "laptop": "laptop"
    },
    "station_roles": {
      "counter": "workstation",
      "table": "surface",
      "floor": "surface"
    }
  },
  "resources": [],
  "laws": [],
  "not_modeled": ["Real clock time and the exact time the cafe closes."]
}

