}"}, {"role": "assistant", "content": "{"schema_version": "world-substrate-authoring-bundle/v0", "world": {"id": "cafe-closing", "label": "Cafe at Closing Time", "summary": "Cafe staff tidy the room while a customer lingers with coffee and ongoing cafe work remains possible.", "location": "cafe", "content_version": 1}, "components": [{"name": "worker", "fields": [{"name": "role", "type": "string", "default": "barista"}, {"name": "energy", "type": "integer", "default": 8}]}, {"name": "customer", "fields": [{"name": "coffee_servings", "type": "integer", "default": 1}, {"name": "waiting_for_coffee", "type": "boolean", "default": false}]}, {"name": "chair", "fields": [{"name": "on", "type": "entity_ref", "default": "floor"}, {"name": "stacked", "type": "boolean", "default": false}]}, {"name": "surface", "fields": [{"name": "wet", "type": "boolean", "default": false}, {"name": "on", "type": "entity_ref_or_null", "default": null}]}, {"name": "tray", "fields": [{"name": "cups", "type": "integer", "default": 3}, {"name": "on", "type": "entity_ref", "default": "waiter"}, {"name": "upright", "type": "boolean", "default": true}]}, {"name": "plate_stack", "fields": [{"name": "count", "type": "integer", "default": 8}, {"name": "upright", "type": "boolean", "default": true}, {"name": "on", "type": "entity_ref", "default": "counter"}]}, {"name": "mop", "fields": [{"name": "on", "type": "entity_ref", "default": "cleaner"}]}, {"name": "coffee", "fields": [{"name": "servings", "type": "integer", "default": 1}, {"name": "on", "type": "entity_ref", "default": "table"}]}, {"name": "laptop", "fields": [{"name": "on", "type": "entity_ref", "default": "table"}, {"name": "broken", "type": "boolean", "default": false}]}], "entities": [{"id": "cafe", "label": "Cafe", "categories": ["place"], "components": {}}, {"id": "barista", "label": "Barista", "categories": ["actor", "barista"], "location": "cafe", "components": {"worker": {"role": "barista", "energy": 8}}}, {"id": "waiter", "label": "Wai