{"event_id":"r2-e00003","round":2,"by":"cleaner","move":"mop-floor","changed":"entities.floor.components.surface.wet: true -> false","said":"Tidying the wet floor is my job, and mopping is more useful than disturbing the waiter or customer."}
{"event_id":"r2-e00005","round":2,"by":"customer","move":"knock-over","changed":"entities.tray.components.tray.upright: true -> false","said":"I have no coffee-serving option available, and I am choosing to cause a disturbance rather than simply wait."}
