{"event_id":"r5-e00003","round":5,"by":"customer","move":"sip-coffee","changed":"entities.coffee.components.coffee.servings: 2 -> 1; entities.customer.components.customer.coffee_servings: 2 -> 1","said":"I want to drink the coffee I have, and sipping it is the only useful action available to me."}
